const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const kalahari = ee.Geometry.Polygon([
    [19.0, -23.0], [25.0, -23.0], [25.0, -29.0], [19.0, -29.0], [19.0, -23.0]
  ]);

  const date1 = ee.Date('2008-08-06');
  const date2 = ee.Date('2009-04-19');

  // Search strategy: MODIS MOD13Q1 for NDVI at 250m resolution
  const getNDVI = function(date) {
    const start = date.advance(-8, 'day');
    const end = date.advance(8, 'day');

    const col = ee.ImageCollection('MODIS/006/MOD13Q1')
      .filterBounds(kalahari)
      .filterDate(start, end)
      .select('NDVI');

    return col.mean().multiply(0.0001); // Apply scale factor
  };

  // 2. Data Acquisition & Check
  const img1 = getNDVI(date1);
  const img2 = getNDVI(date2);

  // Check if collections had data
  const checkImage = function(img, dateStr) {
    const count = img.bandNames().size().getInfo();
    return count > 0;
  };

  if (!checkImage(img1, '2008')) {
    console.log('2008 Images: 0');
    console.log('<answer>C1</answer>');
    return;
  }

  if (!checkImage(img2, '2009')) {
    console.log('2009 Images: 0');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing & Pixel Count Check
  const getStats = function(img) {
    const stats = img.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: kalahari,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    });

    const mean = ee.Number(stats.get('NDVI')).getInfo();
    const count = ee.Number(stats.get('NDVI_count')).getInfo();
    return {mean: mean, count: count};
  };

  const stats1 = getStats(img1);
  const stats2 = getStats(img2);

  console.log(`2008 NDVI: ${stats1.mean.toFixed(3)} (Pixels: ${stats1.count})`);
  console.log(`2009 NDVI: ${stats2.mean.toFixed(3)} (Pixels: ${stats2.count})`);

  // 4. Validation
  if (stats1.count === 0 || stats2.count === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (stats1.mean === null || stats2.mean === null || 
      isNaN(stats1.mean) || isNaN(stats2.mean) ||
      stats1.mean > 1 || stats1.mean < -1 ||
      stats2.mean > 1 || stats2.mean < -1) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 5. Final Answer
  const isGreener = stats2.mean > stats1.mean;
  console.log(isGreener ? '<answer>A</answer>' : '<answer>B</answer>');
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
